    const PLUX_LANG_LOCALES = {
      es: 'es-ES',
      en: 'en-US',
      fr: 'fr-FR',
      de: 'de-DE',
      it: 'it-IT'
    };

    const PLUX_LANG_NAMES = {
      es: 'Español',
      en: 'English',
      fr: 'Français',
      de: 'Deutsch',
      it: 'Italiano'
    };

    function getCurrentLang() {
      const l = (typeof currentLang !== 'undefined' && currentLang) ? currentLang : (localStorage.getItem('Plux_Lang') || 'es');
      return i18n[l] ? l : 'es';
    }
    window.getCurrentLang = getCurrentLang;

    function getLangLocale(lang) {
      const l = lang || getCurrentLang();
      return PLUX_LANG_LOCALES[l] || 'es-ES';
    }
    window.getLangLocale = getLangLocale;

    function getLangName(lang) {
      const l = lang || getCurrentLang();
      return PLUX_LANG_NAMES[l] || 'Español';
    }
    window.getLangName = getLangName;

    function getWikiLang(lang) {
      const l = lang || getCurrentLang();
      return ['es', 'en', 'fr', 'de', 'it'].includes(l) ? l : 'en';
    }
    window.getWikiLang = getWikiLang;

    function lookupI18nKey(langObj, key) {
      if (!langObj || !key) return null;
      const parts = key.split('.');
      let val = langObj;
      for (const p of parts) {
        if (val && typeof val === 'object' && p in val) {
          val = val[p];
        } else {
          return null;
        }
      }
      return typeof val === 'string' ? val : null;
    }

    function t(key, params = {}) {
      if (!key) return '';
      const activeLang = getCurrentLang();
      let val = lookupI18nKey(i18n[activeLang], key);
      if (val === null && activeLang !== 'en') {
        val = lookupI18nKey(i18n['en'], key);
      }
      if (val === null && activeLang !== 'es') {
        val = lookupI18nKey(i18n['es'], key);
      }
      if (val === null) {
        val = key;
      }
      if (typeof val === 'string' && params && typeof params === 'object') {
        for (const p in params) {
          val = val.replace(new RegExp(`\\{${p}\\}`, 'g'), params[p]);
        }
      }
      return val;
    }
    window.t = t;

    function applyDeclarativeI18n(root = document) {
      if (!root || typeof root.querySelectorAll !== 'function') return;
      root.querySelectorAll('[data-i18n]').forEach(node => {
        const key = node.getAttribute('data-i18n');
        const val = t(key);
        if (val && val !== key) node.textContent = val;
      });
      root.querySelectorAll('[data-i18n-html]').forEach(node => {
        const key = node.getAttribute('data-i18n-html');
        const val = t(key);
        if (val && val !== key) node.innerHTML = val;
      });
      root.querySelectorAll('[data-i18n-ph]').forEach(node => {
        const key = node.getAttribute('data-i18n-ph');
        const val = t(key);
        if (val && val !== key) node.placeholder = val;
      });
      root.querySelectorAll('[data-i18n-title]').forEach(node => {
        const key = node.getAttribute('data-i18n-title');
        const val = t(key);
        if (val && val !== key) node.title = val;
      });
      root.querySelectorAll('[data-i18n-aria]').forEach(node => {
        const key = node.getAttribute('data-i18n-aria');
        const val = t(key);
        if (val && val !== key) node.setAttribute('aria-label', val);
      });
      root.querySelectorAll('[data-i18n-alt]').forEach(node => {
        const key = node.getAttribute('data-i18n-alt');
        const val = t(key);
        if (val && val !== key) node.alt = val;
      });
    }
    window.applyDeclarativeI18n = applyDeclarativeI18n;
